-- The 154 doctors Merkezi Klinika publishes, from its own directory.
--
-- Read from merkeziklinika.az on 2026-09-19, in Azerbaijani. The third
-- hospital in this directory, and the largest: it more than doubles it.
--
-- The total is 154 and two independent sources agree on it. The listing page
-- carries 154 profile cards, and the site's own sitemap carries 154 Azerbaijani
-- doctor URLs; comparing the two sets leaves nothing on either side, the only
-- difference being that one doctor is linked by bare id in the sitemap and by
-- name on the page. Ids run from 229 to 622 and are sparse, so probing the
-- range proves nothing and was not relied on.
--
-- None of these doctors asked to be here. Every row is UNCLAIMED with
-- accepts_bookings = 0: the listing repeats what the hospital already
-- publishes, it does not assert that we checked anything, and it cannot take
-- an appointment nobody is watching. A doctor who claims their listing goes to
-- PENDING and is reviewed like any other claim.
--
-- Three of the hospital's own profile links are broken - Prof. Dr. Firdovsi
-- Ibrahimov, T.e.n. Dr. Mahir Dumanov and T.e.n. Dr. Mahire Ismayilova all
-- 404, from the listing page and from the bare id alike. They are listed here
-- anyway, from what their cards on the directory publish: name, specialty,
-- role and photograph, with education and experience left NULL. Leaving a
-- doctor out because their own hospital's link is broken would be the one
-- mistake this directory cannot afford.
--
-- Ten more doctors publish no education, experience or length of service, so
-- those fields are NULL for them. Everywhere else years_experience is the
-- hospital's own figure, which it states as "30+ il" and which is recorded as
-- the number: this source publishes it directly rather than leaving it to be
-- worked out from a graduation year.
--
-- Every one of the 154 has a portrait. They are served through the site's own
-- image proxy because the storage host it points at, admin.merkeziklinika.az,
-- does not resolve publicly at all.
--
-- Data only.

-- Two departments this hospital has that the taxonomy did not.
--
-- Neonatology is what a parent of a newborn actually searches for, and four
-- doctors here are neonatologists; folding them into paediatrics would lose
-- exactly the distinction that matters at that moment. Embryology is listed
-- with patient_facing = 0 for the same reason pathology is: three of these
-- doctors are embryologists, they belong in a complete listing, and nobody
-- makes an appointment with one.
INSERT IGNORE INTO specialty (code, name_az, name_en, name_ru, patient_facing, ai_specialty_code, sort_order) VALUES
('neonatology','Neonatologiya','Neonatology','Неонатология',1,'pediatric',111),
('embryology','Embriologiya','Embryology','Эмбриология',0,NULL,112);

INSERT INTO clinic (name, slug, address, city, phone, description, active, created_at, updated_at)
SELECT * FROM (SELECT
    'Mərkəzi Klinika' AS name,
    'merkezi-klinika' AS slug,
    'Parlament prospekti 76, AZ1006, Bakı' AS address,
    'Bakı' AS city,
    '+994 12 105' AS phone,
    'Mərkəzi Klinika, Bakı. Siyahı klinikanın merkeziklinika.az saytındakı həkim kataloqu əsasında hazırlanıb.' AS description,
    1 AS active, NOW() AS created_at, NOW() AS updated_at) AS c
WHERE NOT EXISTS (SELECT 1 FROM clinic WHERE slug = 'merkezi-klinika');

SET @clinic_id = (SELECT id FROM clinic WHERE slug = 'merkezi-klinika');

